(1, 'rom88762', 'jeanrs', 'Comprovante', '1704644655', '', '<p>Favor liberar o acesso. Obrigado<br></p>', 'S', 'S', 2, 1, 2, 'N', 'N', 'N'),
(2, 'egg89721', 'jeanrs', 'Comprovante', '1704669597', '', '<p>Comprovante usuário egg89721</p>', 'N', 'S', 2, 1, 2, 'N', 'N', 'N'),
(3, 'tel33673', 'jeanrs', 'Suporte técnico ', '1705096037', NULL, '<p>Boa tarde, O servidor ficar desconectado o meu aparelho e dando os canais codificado, como posso resolver esse problema.</p>', 'N', 'S', 2, 1, 5, 'N', 'N', 'N'),
(4, 'ale10315', 'jeanrs', 'Sem cs', '1705103520', NULL, '<p>Boa noite, aqui no meu aparelho atto net 5 sumiu as informações para acesso ao cs. Poderiam me enviar por gentileza.&nbsp;</p>', 'S', 'S', 2, 1, 5, 'N', 'N', 'N'),
(5, 'nal65768', 'jeanrs', 'Comprovante', '1705241580', '', '<p>Envio do pagamento mensal</p>', 'S', 'S', 2, 1, 2, 'N', 'N', 'N'),
(6, 'raq79825', 'jeanrs', 'Comprovante', '1705494046', '', '<p>Bom dia</p><p>Em quanto tempo fica liberado?</p>', 'S', 'S', 2, 1, 2, 'N', 'N', 'N'),
(7, 'app1966', 'jeanrs', 'CS', '1705521221', NULL, '<p>Tem CS da net cabo?</p>', 'S', 'S', 4, 1, 5, 'N', 'S', 'N'),
(8, 'and79111', 'jeanrs', 'Comprovante', '1705532500', '', '<p>Renovação 3 meses, segue em anexo o comprovante</p><p><br></p>', 'S', 'S', 2, 1, 2, 'N', 'N', 'N'),
(9, 'hen75798', 'jeanrs', 'Comprovante', '1705716313', '', '<p>Olá, segue em anexo comprovante&nbsp;</p>', 'N', 'S', 2, 1, 2, 'N', 'N', 'N'),
(10, 'ren86223', 'jeanrs', 'teste nao eh 48 horas como consta no email', '1706317131', NULL, '<p>Nao fiz teste porque o periodo informado no email nao confere.</p>', 'N', 'S', 2, 1, 5, 'N', 'N', 'N'),
(11, 'app1966', 'jeanrs', 'Informação', '1706566523', NULL, '<p>Você não tem NET cabo região triangulo mineiro/sul? Se tiver mande um teste que estou interessado.</p>', 'S', 'S', 4, 1, 5, 'N', 'S', 'N');
