(12, 'lui53883', 'jeanrs', 'Comprovante', '1707164799', NULL, '<p>Boa tarde!&nbsp;<br><br>Em anexo comprovante:&nbsp;<br><br><img src=\"data:image/png;base64,\" alt=\"\"></p><img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"width: 400px;\"><p><br></p>', 'S', 'S', 2, 1, 2, 'N', 'N', 'N');
