(22, 'ans22032', 'jeanrs', 'Comprovante', '1720298268', '', '<p>Plano Semestral</p>', 'S', 'S', 2, 1, 2, 'N', 'N', 'N'),
(23, 'rom88762', 'jeanrs', 'Comprovante', '1720532539', '', '<p>Segue comprovante de pagto por mais 180 dias. Aguardo liberação do sinal. Obrigado<br></p>', 'S', 'S', 2, 1, 2, 'N', 'N', 'N'),
(24, 'idair006781', 'jeanrs', 'Comprovante', '1724270867', '', '<p><span style=\"color: rgb(101, 109, 120);\">Informação de pagamento de cs 8 cliente no primeiro e 10 no segundo</span><br></p>', 'N', 'S', 2, 1, 2, 'N', 'N', 'N'),
