(26, 'tam49788', 'jeanrs', 'Receptor codificado', '1736036586', NULL, '<p>Olá , boa noite !!</p><p>Meu receptor não está funcionando, só fica na imagem codificado .</p><p>Verificando meu painel ainda faltam 6 dias para renovação.</p><p>Pode verificar por gentileza, o que está acontecendo??</p><p><br></p>', 'S', 'S', 2, 1, 5, 'N', 'N', 'N'),
(27, 'rosildo0601', 'Joaopedro16', 'Não está aparecendo no meu painel pra mim criar o teste ', '1736212876', '', 'Não está aparecendo no meu painel pra mim criar o teste&nbsp;', 'S', 'S', 2, 1, 5, 'N', 'N', 'N'),
